import re


def slugify(text):
    """Convert arbitrary text into a lowercase, hyphen-separated slug."""
    if text is None:
        return ''
    text = str(text).lower()
    # Replace any run of non-alphanumeric characters with a single hyphen.
    text = re.sub(r'[^a-z0-9]+', '-', text)
    # Trim leading/trailing hyphens.
    return text.strip('-')

