def totals_by_category(csv_text):
    totals = {}
    lines = csv_text.splitlines()
    started = False
    for line in lines:
        if not line.strip():
            continue
        if not started:
            started = True
            header = [h.strip().lower() for h in line.split(",")]
            if "category" in header and "amount" in header:
                cat_idx = header.index("category")
                amt_idx = header.index("amount")
                continue
            cat_idx, amt_idx = 0, 1
        parts = [p.strip() for p in line.split(",")]
        if len(parts) <= max(cat_idx, amt_idx):
            continue
        category = parts[cat_idx]
        amount = int(parts[amt_idx])
        totals[category] = totals.get(category, 0) + amount
    return totals

